import functools
from unittest import mock
from sphinx.ext.napoleon import _skip_member, Config

def simple_decorator(f):
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

class Foo:
    @simple_decorator
    def __init__(self):
        """init doc"""
    @simple_decorator
    def __decorated_func__(self):
        """doc"""
    def _private_doc(self):
        """doc"""
    def plain(self):
        """doc"""

app = mock.Mock()
app.config = Config()
app.config.napoleon_include_init_with_doc = True
app.config.napoleon_include_special_with_doc = True
app.config.napoleon_include_private_with_doc = True

# 1. the issue scenario: decorated __init__ must NOT be skipped
r = _skip_member(app, 'class', '__init__', Foo.__init__, True, mock.Mock())
print('decorated __init__ ->', repr(r)); assert r is False, r

# 2. decorated special method
r = _skip_member(app, 'class', '__decorated_func__', Foo.__decorated_func__, True, mock.Mock())
print('decorated special ->', repr(r)); assert r is False, r

# 3. undoc decorated member: still default (None)
class Bar:
    @simple_decorator
    def meth(self):
        pass
r = _skip_member(app, 'class', 'meth', Bar.meth, True, mock.Mock())
print('undoc decorated ->', repr(r)); assert r is None, r

# 4. plain documented private member: unchanged behavior
r = _skip_member(app, 'class', '_private_doc', Foo._private_doc, True, mock.Mock())
print('plain private ->', repr(r)); assert r is False, r

# 5. plain documented method (not init/special/private): None
r = _skip_member(app, 'class', 'plain', Foo.plain, True, mock.Mock())
print('plain method ->', repr(r)); assert r is None, r

# 6. module-level function (what='module' path untouched)
@simple_decorator
def modfunc():
    """doc"""
r = _skip_member(app, 'module', 'modfunc', modfunc, True, mock.Mock())
print('module func ->', repr(r)); assert r is None, r

print('ALL BEHAVIOR CHECKS OK')
